477	function parseThresholds(thresholdStrings?: string[]): { thresholds: Record<string, number> | undefined; validationError?: string } {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return { thresholds: undefined };
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	
484	  for (const thresholdStr of thresholdStrings) {
485	    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
486	    if (!match) {
487	      return {
488	        thresholds: undefined,
489	        validationError: `Malformed threshold: "${thresholdStr}". Expected format: <metric>=<number>`
490	      };
491	    }
492	
493	    const [, metricId, valueStr] = match;
494	    const value = Number.parseFloat(valueStr);
495	
496	    if (Number.isNaN(value) || value < 0 || value > 1) {
497	      return {
498	        thresholds: undefined,
499	        validationError: `Invalid threshold value: "${valueStr}". Minimum must be a number between 0 and 1.`
500	      };
501	    }
502	
503	    thresholds[metricId] = value;
504	  }
505	
506	  return { thresholds };
507	}
