509	function validateThresholdMetrics(
510	  thresholds: Record<string, number>,
511	  evaluations: Array<{ id: string }>
512	): { valid: boolean; error?: string } {
513	  const validMetricIds = evaluations.map((m) => m.id);
514	
515	  for (const metricId of Object.keys(thresholds)) {
516	    if (!validMetricIds.includes(metricId)) {
517	      return {
518	        valid: false,
519	        error: `Unknown metric: "${metricId}". Valid metrics are: ${validMetricIds.join(', ')}`
520	      };
521	    }
522	  }
523	
524	  return { valid: true };
525	}
